static inline __attribute__((__always_inline__)) uint32_t CommandRestoreDistanceCode( const Command* self, const BrotliDistanceParams* dist) {
  if ((self->dist_prefix_ & 0x3FFu) < 16 + dist->num_direct_distance_codes) {
    return self->dist_prefix_ & 0x3FFu;
