static inline __attribute__((__always_inline__)) size_t FindMatchLengthWithLimit(const uint8_t* s1, const uint8_t* s2, size_t limit) {
  size_t matched = 0;
  size_t limit2 = (limit >> 3) + 1;
  while ((__builtin_expect(!!(--limit2), 1))) {
    if ((__builtin_expect(BrotliUnalignedRead64(s2) == BrotliUnalignedRead64(s1 + matched), 0))) {
      s2 += 8;
      matched += 8;
    } else {
      uint64_t x = BrotliUnalignedRead64(s2) ^ BrotliUnalignedRead64(s1 + matched);
      size_t matching_bits = (size_t)__builtin_ctzll(x);
      matched += matching_bits >> 3;
      return matched;
    }
  }
  limit = (limit & 7) + 1;
  while (--limit) {
    if ((__builtin_expect(!!(s1[matched] == *s2), 1))) {
      ++s2;
      ++matched;
    } else {
      return matched;
    }
  }
  return matched;
}

