static inline __attribute__((__always_inline__)) BackwardMatch* StoreAndFindMatchesH10( H10* restrict self, const uint8_t* restrict data, const size_t cur_ix, const size_t ring_buffer_mask, const size_t max_length, const size_t max_backward, size_t* const restrict best_len, BackwardMatch* restrict matches) {
