extern __inline __attribute__ ((__gnu_inline__)) int __attribute__ ((__nothrow__ )) mknodat (int __fd, const char *__path, __mode_t __mode, __dev_t __dev) {
  return __xmknodat (0, __fd, __path, __mode, &__dev);
}

extern __inline __attribute__ ((__gnu_inline__)) int __attribute__ ((__nothrow__ )) stat (const char *__path, struct stat *__statbuf) {
  return __xstat (1, __path, __statbuf);
}

extern __inline __attribute__ ((__gnu_inline__)) int __attribute__ ((__nothrow__ )) lstat (const char *__path, struct stat *__statbuf) {
  return __lxstat (1, __path, __statbuf);
}

extern __inline __attribute__ ((__gnu_inline__)) int __attribute__ ((__nothrow__ )) fstatat (int __fd, const char *__filename, struct stat *__statbuf, int __flag) {
  return __fxstatat (1, __fd, __filename, __statbuf, __flag);
}

static int ParseInt(const char* s, int low, int high, int* result) {
  int value = 0;
  int i;
  for (i = 0; i < 5; ++i) {
    char c = s[i];
    if (c == 0) break;
    if (s[i] < '0' || s[i] > '9') return 0;
    value = (10 * value) + (c - '0');
  }
  if (i == 0) return 0;
  if (i > 1 && s[0] == '0') return 0;
  if (s[i] != 0) return 0;
  if (value < low || value > high) return 0;
  *result = value;
  return 1;
}

static const char* FileName(const char* path) {
  const char* separator_position = strrchr(path, '/');
  if (separator_position) path = separator_position + 1;
  separator_position = strrchr(path, '\\');
  if (separator_position) path = separator_position + 1;
  return path;
}

static Command ParseAlias(const char* name) {
  const char* unbrotli = "unbrotli";
  size_t unbrotli_len = strlen(unbrotli);
  name = FileName(name);
  if (strncmp(name, unbrotli, unbrotli_len) == 0) {
    char terminator = name[unbrotli_len];
    if (terminator == 0 || terminator == '.') return COMMAND_DECOMPRESS;
  }
  return COMMAND_COMPRESS;
}

static Command ParseParams(Context* params) {
  int argc = params->argc;
  char** argv = params->argv;
  int i;
  int next_option_index = 0;
  size_t input_count = 0;
  size_t longest_path_len = 1;
  int command_set = 0;
  int quality_set = 0;
  int output_set = 0;
  int keep_set = 0;
  int lgwin_set = 0;
  int suffix_set = 0;
  int after_dash_dash = 0;
  Command command = ParseAlias(argv[0]);
  for (i = 1; i < argc; ++i) {
    const char* arg = argv[i];
    size_t arg_len = arg ? strlen(arg) : 0;
    if (arg_len == 0) {
      params->not_input_indices[next_option_index++] = i;
      continue;
    }
    if (next_option_index > (20 - 2)) {
      fprintf(stderr, "too many options passed\n");
      return COMMAND_INVALID;
    }
    if (after_dash_dash || arg[0] != '-' || arg_len == 1) {
      input_count++;
      if (longest_path_len < arg_len) longest_path_len = arg_len;
      continue;
    }
    params->not_input_indices[next_option_index++] = i;
    if (arg_len == 2 && arg[1] == '-') {
      after_dash_dash = 1;
      continue;
    }
    if (arg[1] != '-') {
      size_t j;
      for (j = 1; j < arg_len; ++j) {
        char c = arg[j];
        if (c >= '0' && c <= '9') {
          if (quality_set) {
            fprintf(stderr, "quality already set\n");
            return COMMAND_INVALID;
          }
          quality_set = 1;
          params->quality = c - '0';
          continue;
        } else if (c == 'c') {
          if (output_set) {
            fprintf(stderr, "write to standard output already set\n");
            return COMMAND_INVALID;
          }
          output_set = 1;
          params->write_to_stdout = 1;
          continue;
        } else if (c == 'd') {
          if (command_set) {
            fprintf(stderr, "command already set when parsing -d\n");
            return COMMAND_INVALID;
          }
          command_set = 1;
          command = COMMAND_DECOMPRESS;
          continue;
        } else if (c == 'f') {
          if (params->force_overwrite) {
            fprintf(stderr, "force output overwrite already set\n");
            return COMMAND_INVALID;
          }
          params->force_overwrite = 1;
          continue;
        } else if (c == 'h') {
          return COMMAND_HELP;
        } else if (c == 'j' || c == 'k') {
          if (keep_set) {
            fprintf(stderr, "argument --rm / -j or --keep / -k already set\n");
            return COMMAND_INVALID;
          }
          keep_set = 1;
          params->junk_source = (!!(c == 'j') ? 1 : 0);
          continue;
        } else if (c == 'n') {
          if (!params->copy_stat) {
            fprintf(stderr, "argument --no-copy-stat / -n already set\n");
            return COMMAND_INVALID;
          }
          params->copy_stat = 0;
          continue;
        } else if (c == 't') {
          if (command_set) {
            fprintf(stderr, "command already set when parsing -t\n");
            return COMMAND_INVALID;
          }
          command_set = 1;
          command = COMMAND_TEST_INTEGRITY;
          continue;
        } else if (c == 'v') {
          if (params->verbosity > 0) {
            fprintf(stderr, "argument --verbose / -v already set\n");
            return COMMAND_INVALID;
          }
          params->verbosity = 1;
          continue;
        } else if (c == 'V') {
          return COMMAND_VERSION;
        } else if (c == 'Z') {
          if (quality_set) {
            fprintf(stderr, "quality already set\n");
            return COMMAND_INVALID;
          }
          quality_set = 1;
          params->quality = 11;
          continue;
        }
        if (c != 'o' && c != 'q' && c != 'w' && c != 'D' && c != 'S') {
          fprintf(stderr, "invalid argument -%c\n", c);
          return COMMAND_INVALID;
        }
        if (j + 1 != arg_len) {
          fprintf(stderr, "expected parameter for argument -%c\n", c);
          return COMMAND_INVALID;
        }
        i++;
        if (i == argc || !argv[i] || argv[i][0] == 0) {
          fprintf(stderr, "expected parameter for argument -%c\n", c);
          return COMMAND_INVALID;
        }
        params->not_input_indices[next_option_index++] = i;
        if (c == 'o') {
          if (output_set) {
            fprintf(stderr, "write to standard output already set (-o)\n");
            return COMMAND_INVALID;
          }
          params->output_path = argv[i];
        } else if (c == 'q') {
          if (quality_set) {
            fprintf(stderr, "quality already set\n");
            return COMMAND_INVALID;
          }
          quality_set = ParseInt(argv[i], 0, 11, &params->quality);
          if (!quality_set) {
            fprintf(stderr, "error parsing quality value [%s]\n", argv[i]);
            return COMMAND_INVALID;
          }
        } else if (c == 'w') {
          if (lgwin_set) {
            fprintf(stderr, "lgwin parameter already set\n");
            return COMMAND_INVALID;
          }
          lgwin_set = ParseInt(argv[i], 0, 24, &params->lgwin);
          if (!lgwin_set) {
            fprintf(stderr, "error parsing lgwin value [%s]\n", argv[i]);
            return COMMAND_INVALID;
          }
          if (params->lgwin != 0 && params->lgwin < 10) {
            fprintf(stderr, "lgwin parameter (%d) smaller than the minimum (%d)\n", params->lgwin, 10);
            return COMMAND_INVALID;
          }
        } else if (c == 'S') {
          if (suffix_set) {
            fprintf(stderr, "suffix already set\n");
            return COMMAND_INVALID;
          }
          suffix_set = 1;
          params->suffix = argv[i];
        }
      }
    } else {
      arg = &arg[2];
      if (strcmp("best", arg) == 0) {
        if (quality_set) {
          fprintf(stderr, "quality already set\n");
          return COMMAND_INVALID;
        }
        quality_set = 1;
        params->quality = 11;
      } else if (strcmp("decompress", arg) == 0) {
        if (command_set) {
          fprintf(stderr, "command already set when parsing --decompress\n");
          return COMMAND_INVALID;
        }
        command_set = 1;
        command = COMMAND_DECOMPRESS;
      } else if (strcmp("force", arg) == 0) {
        if (params->force_overwrite) {
          fprintf(stderr, "force output overwrite already set\n");
          return COMMAND_INVALID;
        }
        params->force_overwrite = 1;
      } else if (strcmp("help", arg) == 0) {
        return COMMAND_HELP;
      } else if (strcmp("keep", arg) == 0) {
        if (keep_set) {
          fprintf(stderr, "argument --rm / -j or --keep / -k already set\n");
          return COMMAND_INVALID;
        }
        keep_set = 1;
        params->junk_source = 0;
      } else if (strcmp("no-copy-stat", arg) == 0) {
        if (!params->copy_stat) {
          fprintf(stderr, "argument --no-copy-stat / -n already set\n");
          return COMMAND_INVALID;
        }
        params->copy_stat = 0;
      } else if (strcmp("rm", arg) == 0) {
        if (keep_set) {
          fprintf(stderr, "argument --rm / -j or --keep / -k already set\n");
          return COMMAND_INVALID;
        }
        keep_set = 1;
        params->junk_source = 1;
      } else if (strcmp("stdout", arg) == 0) {
        if (output_set) {
          fprintf(stderr, "write to standard output already set\n");
          return COMMAND_INVALID;
        }
        output_set = 1;
        params->write_to_stdout = 1;
      } else if (strcmp("test", arg) == 0) {
        if (command_set) {
          fprintf(stderr, "command already set when parsing --test\n");
          return COMMAND_INVALID;
        }
        command_set = 1;
        command = COMMAND_TEST_INTEGRITY;
      } else if (strcmp("verbose", arg) == 0) {
        if (params->verbosity > 0) {
          fprintf(stderr, "argument --verbose / -v already set\n");
          return COMMAND_INVALID;
        }
        params->verbosity = 1;
      } else if (strcmp("version", arg) == 0) {
        return COMMAND_VERSION;
      } else {
        const char* value = strrchr(arg, '=');
        size_t key_len;
        if (!value || value[1] == 0) {
          fprintf(stderr, "must pass the parameter as --%s=value\n", arg);
          return COMMAND_INVALID;
        }
        key_len = (size_t)(value - arg);
        value++;
        if (strncmp("lgwin", arg, key_len) == 0) {
          if (lgwin_set) {
            fprintf(stderr, "lgwin parameter already set\n");
            return COMMAND_INVALID;
          }
          lgwin_set = ParseInt(value, 0, 24, &params->lgwin);
          if (!lgwin_set) {
            fprintf(stderr, "error parsing lgwin value [%s]\n", value);
            return COMMAND_INVALID;
          }
          if (params->lgwin != 0 && params->lgwin < 10) {
            fprintf(stderr, "lgwin parameter (%d) smaller than the minimum (%d)\n", params->lgwin, 10);
            return COMMAND_INVALID;
          }
        } else if (strncmp("large_window", arg, key_len) == 0) {
          if (lgwin_set) {
            fprintf(stderr, "lgwin parameter already set\n");
            return COMMAND_INVALID;
          }
          lgwin_set = ParseInt(value, 0, 30, &params->lgwin);
          if (!lgwin_set) {
            fprintf(stderr, "error parsing lgwin value [%s]\n", value);
            return COMMAND_INVALID;
          }
          if (params->lgwin != 0 && params->lgwin < 10) {
            fprintf(stderr, "lgwin parameter (%d) smaller than the minimum (%d)\n", params->lgwin, 10);
            return COMMAND_INVALID;
          }
        } else if (strncmp("output", arg, key_len) == 0) {
          if (output_set) {
            fprintf(stderr, "write to standard output already set (--output)\n");
            return COMMAND_INVALID;
          }
          params->output_path = value;
        } else if (strncmp("quality", arg, key_len) == 0) {
          if (quality_set) {
            fprintf(stderr, "quality already set\n");
            return COMMAND_INVALID;
          }
          quality_set = ParseInt(value, 0, 11, &params->quality);
          if (!quality_set) {
            fprintf(stderr, "error parsing quality value [%s]\n", value);
            return COMMAND_INVALID;
          }
        } else if (strncmp("suffix", arg, key_len) == 0) {
          if (suffix_set) {
            fprintf(stderr, "suffix already set\n");
            return COMMAND_INVALID;
          }
          suffix_set = 1;
          params->suffix = value;
        } else {
          fprintf(stderr, "invalid parameter: [%s]\n", arg);
          return COMMAND_INVALID;
        }
      }
    }
  }
  params->input_count = input_count;
  params->longest_path_len = longest_path_len;
  params->decompress = (command == COMMAND_DECOMPRESS);
  params->test_integrity = (command == COMMAND_TEST_INTEGRITY);
  if (input_count > 1 && output_set) return COMMAND_INVALID;
  if (params->test_integrity) {
    if (params->output_path) return COMMAND_INVALID;
    if (params->write_to_stdout) return COMMAND_INVALID;
  }
  if (strchr(params->suffix, '/') || strchr(params->suffix, '\\')) {
    return COMMAND_INVALID;
  }
  return command;
}

static void PrintVersion(void) {
  int major = 0x1000009 >> 24;
  int minor = (0x1000009 >> 12) & 0xFFF;
  int patch = 0x1000009 & 0xFFF;
  fprintf(stdout, "brotli %d.%d.%d\n", major, minor, patch);
}

static void PrintHelp(const char* name, int error) {
  FILE* media = error ? stderr : stdout;
  fprintf(media, "Usage: %s [OPTION]... [FILE]...
", name);
  fprintf(media, "Options:
" "  -#                          compression level (0-9)
" "  -c, --stdout                write on standard output
" "  -d, --decompress            decompress
" "  -f, --force                 force output file overwrite
" "  -h, --help                  display this help and exit
");
  fprintf(media, "  -j, --rm                    remove source file(s)
" "  -k, --keep                  keep source file(s) (default)
" "  -n, --no-copy-stat          do not copy source file(s) attributes
" "  -o FILE, --output=FILE      output file (only if 1 input file)
");
  fprintf(media, "  -q NUM, --quality=NUM       compression level (%d-%d)
", 0, 11);
  fprintf(media, "  -t, --test                  test compressed file integrity
" "  -v, --verbose               verbose mode
");
  fprintf(media, "  -w NUM, --lgwin=NUM         set LZ77 window size (0, %d-%d)
" "                              window size = 2**NUM - 16
" "                              0 lets compressor choose the optimal value
", 10, 24);
  fprintf(media, "  --large_window=NUM          use incompatible large-window brotli
" "                              bitstream with window size (0, %d-%d)
" "                              WARNING: this format is not compatible
" "                              with brotli RFC 7932 and may not be
" "                              decodable with regular brotli decoders
", 10, 30);
  fprintf(media, "  -S SUF, --suffix=SUF        output file suffix (default:'%s')
", ".br");
  fprintf(media, "  -V, --version               display version and exit
" "  -Z, --best                  use best compression level (11) (default)
" "Simple options could be coalesced, i.e. '-9kf' is equivalent to '-9 -k -f'.
" "With no FILE, or when FILE is -, read standard input.
" "All arguments after '--' are treated as files.
");
}

static const char* PrintablePath(const char* path) {
  return path ? path : "con";
}

static int OpenInputFile(const char* input_path, FILE** f) {
  *f = ((void*)0);
  if (!input_path) {
    *f = fdopen((0), "rb");
    return 1;
  }
  *f = fopen(input_path, "rb");
  if (!*f) {
    fprintf(stderr, "failed to open input file [%s]: %s\n", PrintablePath(input_path), strerror((*__errno_location ())));
    return 0;
  }
  return 1;
}

static int OpenOutputFile(const char* output_path, FILE** f, int force) {
  int fd;
  *f = ((void*)0);
  if (!output_path) {
    *f = fdopen((1), "wb");
    return 1;
  }
  fd = open(output_path, 0100 | (force ? 0 : 0200) | 01 | 01000, 0400 | 0200);
  if (fd < 0) {
    fprintf(stderr, "failed to open output file [%s]: %s\n", PrintablePath(output_path), strerror((*__errno_location ())));
    return 0;
  }
  *f = fdopen(fd, "wb");
  if (!*f) {
    fprintf(stderr, "failed to open output file [%s]: %s\n", PrintablePath(output_path), strerror((*__errno_location ())));
    return 0;
  }
  return 1;
}

static int64_t FileSize(const char* path) {
  FILE* f = fopen(path, "rb");
  int64_t retval;
  if (f == ((void*)0)) {
    return -1;
  }
  if (fseek(f, 0L, 2) != 0) {
    fclose(f);
    return -1;
  }
  retval = ftell(f);
  if (fclose(f) != 0) {
    return -1;
  }
  return retval;
}

static void CopyStat(const char* input_path, const char* output_path) {
  struct stat statbuf;
  struct utimbuf times;
  int res;
  if (input_path == 0 || output_path == 0) {
    return;
  }
  if (stat(input_path, &statbuf) != 0) {
    return;
  }
  times.actime = statbuf.st_atim.tv_sec;
  times.modtime = statbuf.st_mtim.tv_sec;
  utime(output_path, &times);
  res = chmod(output_path, statbuf.st_mode & ((0400|0200|0100) | ((0400|0200|0100) >> 3) | (((0400|0200|0100) >> 3) >> 3)));
  if (res != 0) {
    fprintf(stderr, "setting access bits failed for [%s]: %s\n", PrintablePath(output_path), strerror((*__errno_location ())));
  }
  res = chown(output_path, (uid_t)-1, statbuf.st_gid);
  if (res != 0) {
    fprintf(stderr, "setting group failed for [%s]: %s\n", PrintablePath(output_path), strerror((*__errno_location ())));
  }
  res = chown(output_path, statbuf.st_uid, (gid_t)-1);
  if (res != 0) {
    fprintf(stderr, "setting user failed for [%s]: %s\n", PrintablePath(output_path), strerror((*__errno_location ())));
  }
}

static int NextFile(Context* context) {
  const char* arg;
  size_t arg_len;
  context->iterator++;
  context->input_file_length = -1;
  if (context->input_count == 0) {
    if (context->iterator > 1) return 0;
    context->current_input_path = ((void*)0);
    context->current_output_path = context->output_path;
    return 1;
  }
  while (context->iterator == context->not_input_indices[context->ignore]) {
    context->iterator++;
    context->ignore++;
  }
  if (context->iterator >= context->argc) return 0;
  arg = context->argv[context->iterator];
  arg_len = strlen(arg);
  if (arg_len == 1 && arg[0] == '-') {
    context->current_input_path = ((void*)0);
    context->current_output_path = context->output_path;
    return 1;
  }
  context->current_input_path = arg;
  context->input_file_length = FileSize(arg);
  context->current_output_path = context->output_path;
  if (context->output_path) return 1;
  if (context->write_to_stdout) return 1;
  strcpy(context->modified_path, arg);
  context->current_output_path = context->modified_path;
  if (context->decompress) {
    size_t suffix_len = strlen(context->suffix);
    char* name = (char*)FileName(context->modified_path);
    char* name_suffix;
    size_t name_len = strlen(name);
    if (name_len < suffix_len + 1) {
      fprintf(stderr, "empty output file name for [%s] input file\n", PrintablePath(arg));
      context->iterator_error = 1;
      return 0;
    }
    name_suffix = name + name_len - suffix_len;
    if (strcmp(context->suffix, name_suffix) != 0) {
      fprintf(stderr, "input file [%s] suffix mismatch\n", PrintablePath(arg));
      context->iterator_error = 1;
      return 0;
    }
    name_suffix[0] = 0;
    return 1;
  } else {
    strcpy(context->modified_path + arg_len, context->suffix);
    return 1;
  }
}

static int OpenFiles(Context* context) {
  int is_ok = OpenInputFile(context->current_input_path, &context->fin);
  if (!context->test_integrity && is_ok) {
    is_ok = OpenOutputFile( context->current_output_path, &context->fout, context->force_overwrite);
  }
  return is_ok;
}

static int CloseFiles(Context* context, int success) {
  int is_ok = 1;
  if (!context->test_integrity && context->fout) {
    if (!success && context->current_output_path) {
      unlink(context->current_output_path);
    }
    if (fclose(context->fout) != 0) {
      if (success) {
        fprintf(stderr, "fclose failed [%s]: %s\n", PrintablePath(context->current_output_path), strerror((*__errno_location ())));
      }
      is_ok = 0;
    }
    if (success && is_ok && context->copy_stat) {
      CopyStat(context->current_input_path, context->current_output_path);
    }
  }
  if (context->fin) {
    if (fclose(context->fin) != 0) {
      if (is_ok) {
        fprintf(stderr, "fclose failed [%s]: %s\n", PrintablePath(context->current_input_path), strerror((*__errno_location ())));
      }
      is_ok = 0;
    }
  }
  if (success && context->junk_source && context->current_input_path) {
    unlink(context->current_input_path);
  }
  context->fin = ((void*)0);
  context->fout = ((void*)0);
  return is_ok;
}

static void InitializeBuffers(Context* context) {
  context->available_in = 0;
  context->next_in = ((void*)0);
  context->available_out = kFileBufferSize;
  context->next_out = context->output;
  context->total_in = 0;
  context->total_out = 0;
}

static int HasMoreInput(Context* context) {
  return feof(context->fin) ? 0 : 1;
}

static int ProvideInput(Context* context) {
  context->available_in = fread(context->input, 1, kFileBufferSize, context->fin);
  context->total_in += context->available_in;
  context->next_in = context->input;
  if (ferror(context->fin)) {
    fprintf(stderr, "failed to read input [%s]: %s\n", PrintablePath(context->current_input_path), strerror((*__errno_location ())));
    return 0;
  }
  return 1;
}

static int WriteOutput(Context* context) {
  size_t out_size = (size_t)(context->next_out - context->output);
  context->total_out += out_size;
  if (out_size == 0) return 1;
  if (context->test_integrity) return 1;
  fwrite(context->output, 1, out_size, context->fout);
  if (ferror(context->fout)) {
    fprintf(stderr, "failed to write output [%s]: %s\n", PrintablePath(context->current_output_path), strerror((*__errno_location ())));
    return 0;
  }
  return 1;
}

static int ProvideOutput(Context* context) {
  if (!WriteOutput(context)) return 0;
  context->available_out = kFileBufferSize;
  context->next_out = context->output;
  return 1;
}

static int FlushOutput(Context* context) {
  if (!WriteOutput(context)) return 0;
  context->available_out = 0;
  return 1;
}

static void PrintBytes(size_t value) {
  if (value < 1024) {
    fprintf(stderr, "%d B", (int)value);
  } else if (value < 1048576) {
    fprintf(stderr, "%0.3f KiB", (double)value / 1024.0);
  } else if (value < 1073741824) {
    fprintf(stderr, "%0.3f MiB", (double)value / 1048576.0);
  } else {
    fprintf(stderr, "%0.3f GiB", (double)value / 1073741824.0);
  }
}

static void PrintFileProcessingProgress(Context* context) {
  fprintf(stderr, "[%s]: ", PrintablePath(context->current_input_path));
  PrintBytes(context->total_in);
  fprintf(stderr, " -> ");
  PrintBytes(context->total_out);
}

static int DecompressFile(Context* context, BrotliDecoderState* s) {
  BrotliDecoderResult result = BROTLI_DECODER_RESULT_NEEDS_MORE_INPUT;
  InitializeBuffers(context);
  for (;;) {
    if (result == BROTLI_DECODER_RESULT_NEEDS_MORE_INPUT) {
      if (!HasMoreInput(context)) {
