  }
  BrotliBuildAndStoreHuffmanTreeFast(m, histogram, histogram_total, 8, depths, bits, storage_ix, storage);
  if ((!!0)) return 0;
  {
    size_t literal_ratio = 0;
    for (i = 0; i < 256; ++i) {
