    return (!!(BitsEntropy(literal_histo, 256) < max_total_bit_cost) ? 1 : 0);
  }
}

static void EmitUncompressedMetaBlock(const uint8_t* input, size_t input_size, size_t* storage_ix, uint8_t* storage) {
