    if (!SafeReadBits32(br, b->dist_extra_bits[code], &bits)) {
      ++s->block_length[2];
      BrotliBitReaderRestoreState(br, &memento);
      return 0;
    }
  }
  s->distance_code = (int)(b->dist_offset[code] + (bits << s->distance_postfix_bits));
