  switch (p) {
    case BROTLI_PARAM_MODE: state->params.mode = (BrotliEncoderMode)value;
      return 1;
    case BROTLI_PARAM_QUALITY: state->params.quality = (int)value;
      return 1;
    case BROTLI_PARAM_LGWIN: state->params.lgwin = (int)value;
      return 1;
    case BROTLI_PARAM_LGBLOCK: state->params.lgblock = (int)value;
      return 1;
    case BROTLI_PARAM_DISABLE_LITERAL_CONTEXT_MODELING: if ((value != 0) && (value != 1)) return 0;
      state->params.disable_literal_context_modeling = (!!(!!value) ? 1 : 0);
      return 1;
    case BROTLI_PARAM_SIZE_HINT: state->params.size_hint = value;
      return 1;
    case BROTLI_PARAM_LARGE_WINDOW: state->params.large_window = (!!(!!value) ? 1 : 0);
      return 1;
    case BROTLI_PARAM_NPOSTFIX: state->params.dist.distance_postfix_bits = value;
      return 1;
    case BROTLI_PARAM_NDIRECT: state->params.dist.num_direct_distance_codes = value;
      return 1;
