    ChooseContextMap(quality, &bigram_prefix_histo[0], num_literal_contexts, literal_context_map);
  }
}

static int ShouldCompress( const uint8_t* data, const size_t mask, const uint64_t last_flush_pos, const size_t bytes, const size_t num_literals, const size_t num_commands) {
